"""One-off honest E2E: fullstack app generated BY THE MODEL (no scaffold).

Flow: create project (type=fullstack) -> generate via model -> wait done ->
checker -> auto-fix (max 2) -> runner -> real HTTP probe of the generated app.
Reports REAL outcomes; aborts on nothing — failures stay failures.
"""
import json
import os
import socket
import sys
import time
import urllib.request
import urllib.error
from pathlib import Path

ROOT = Path(os.environ["ROOT"])
BASE = os.environ.get("BASE", "http://127.0.0.1:8580")
TS = time.strftime("%H%M%S")
PROJ = f"af4mdl-{TS}"
def _panel_pass() -> str:
    """AF-05.1: credential from env or the secure local file — never a
    hardcoded default; fails safely (non-leaking) when neither exists."""
    pw = os.environ.get("PANEL_PASS") or ""
    if not pw:
        try:
            pw = (Path.home() / ".af-panel" / "panel-pass.txt").read_text(
                encoding="utf-8").strip()
        except OSError:
            pw = ""
    if not pw:
        sys.exit("panel credential missing — set PANEL_PASS or create "
                 "~/.af-panel/panel-pass.txt (0600)")
    return pw


PANEL_PASS = _panel_pass()
_panel_session, _panel_csrf = "", ""


def _panel_login():
    """P6-2: first-run init (idempotent) + login; store session/CSRF."""
    global _panel_session, _panel_csrf
    try:
        st = json.loads(urllib.request.urlopen(
            BASE + "/api/panel/state", timeout=15).read().decode())
    except Exception:
        st = {}
    if not st.get("initialized"):
        self_ = urllib.request.Request(
            BASE + "/api/panel/init", method="POST",
            data=json.dumps({"password": PANEL_PASS}).encode(),
            headers={"Content-Type": "application/json"})
        urllib.request.urlopen(self_, timeout=15).read()
    req = urllib.request.Request(
        BASE + "/api/panel/login", method="POST",
        data=json.dumps({"password": PANEL_PASS}).encode(),
        headers={"Content-Type": "application/json"})
    r = urllib.request.urlopen(req, timeout=15)
    for sc in (r.headers.get_all("Set-Cookie") or []):
        for c in sc.split(", "):
            part = c.split(";")[0]
            if part.startswith("panel_session="):
                _panel_session = part.split("=", 1)[1]
            elif part.startswith("panel_csrf="):
                _panel_csrf = part.split("=", 1)[1]


def api(method, path, body=None, timeout=30):
    data = json.dumps(body).encode() if body is not None else None
    headers = {"Content-Type": "application/json"} if data else {}
    cookies = []
    if _panel_session:
        cookies.append("panel_session=" + _panel_session)
    if _panel_csrf:
        cookies.append("panel_csrf=" + _panel_csrf)     # double-submit
        headers["X-Panel-CSRF"] = _panel_csrf
    if cookies:
        headers["Cookie"] = "; ".join(cookies)
    req = urllib.request.Request(
        BASE + path, method=method, data=data, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return r.status, json.loads(r.read().decode())
    except urllib.error.HTTPError as e:
        try:
            return e.code, json.loads(e.read().decode() or "{}")
        except ValueError:
            return e.code, {}


def main():
    print("== آزمون مدل‌محور Full-Stack (بدون اسکفولد) ==")
    _panel_login()
    code, r = api("POST", "/api/factory/projects", {
        "name": PROJ, "type": "fullstack",
        "description": "مدل‌محور — برنامه یادداشت با API و دیتابیس"})
    print("create:", code, r.get("ok"))
    if code != 201:
        sys.exit(1)

    code, r = api("POST", "/api/factory/generate", {
        "project": PROJ,
        "goal": ("یک برنامه فول‌استک کوچک «مدیریت یادداشت» بساز: بک‌اند پایتون "
                 "server.py در ریشه (پورت از env AI_FACTORY_PORT)؛ دیتابیس "
                 "SQLite در data/app.db با جدول notes(id, title, body, created)؛ "
                 "API با جواب JSON: GET/POST /api/notes و DELETE /api/notes/<id>؛ "
                 "رابط کاربری ui/index.html همراه app.js و style.css که توسط "
                 "همین server.py سرو شود؛ آزمون unittest در tests/test_api.py؛ "
                 "هیچ رمز یا توکنی داخل کد نباشد.")}, timeout=60)
    sid = r.get("session_id")
    print("generate started:", code, sid)
    if code != 200:
        sys.exit(1)

    done = False
    for _ in range(70):                      # ~8 min
        time.sleep(7)
        code, d = api("GET", f"/api/factory/generation?project={PROJ}")
        if d.get("done"):
            done = True
            break
    print("generation done:", done)

    d = ROOT / "projects" / PROJ
    have = sorted(p.as_posix().split(f"{PROJ}/", 1)[-1]
                  for p in d.rglob("*")
                  if p.is_file() and "__pycache__" not in p.parts
                  and ".factory" not in p.parts)
    print("files:", have)

    code, r = api("GET", f"/api/factory/check?project={PROJ}")
    res = (r or {}).get("result") or {}
    errors = res.get("errors", [])
    print("errors after generation:", [e.get("kind") for e in errors])

    if errors:
        print("starting auto-fix (2 attempts real model)…")
        t0 = time.time()
        code, r = api("POST", "/api/factory/fix", {
            "project": PROJ, "attempts": 2}, timeout=300)
        print("fix:", code, json.dumps(r, ensure_ascii=False)[:400] if r else "")
        code, r = api("GET", f"/api/factory/check?project={PROJ}")
        res = (r or {}).get("result") or {}
        errors2 = res.get("errors", [])
        print("errors after fix (%.0fs):" % (time.time() - t0),
              [e.get("kind") for e in errors2])

    # run the REAL backend
    code, r = api("POST", "/api/factory/run", {"project": PROJ}, timeout=60)
    port = r.get("port")
    ok_run = code == 200 and r.get("ok") and r.get("running")
    print("run:", code, "running=", r.get("running"), "port=", port)
    if not (ok_run and port):
        api("POST", "/api/factory/delete", {"project": PROJ, "confirm": True})
        sys.exit(1)
    base = "http://127.0.0.1:%d" % port

    # probe the generated app over real HTTP
    for _ in range(20):
        try:
            with urllib.request.urlopen(base + "/", timeout=10) as resp:
                body = resp.read(200).decode("utf-8", "replace")
            print("GET / ->", resp.status, "| head:", body[:80].replace("\n", " "))
            break
        except Exception as exc:            # noqa: BLE001
            time.sleep(1.5)
    else:
        print("GET / failed")

    try:
        with urllib.request.urlopen(base + "/api/notes", timeout=10) as resp:
            print("GET /api/notes ->", resp.status, resp.read()[:120].decode("utf-8", "replace"))
    except urllib.error.HTTPError as e:
        print("GET /api/notes ->", e.code, e.read()[:120].decode("utf-8", "replace"))
    except Exception as exc:                # noqa: BLE001
        print("GET /api/notes error:", exc)

    # POST a real note if the API supports it (honest outcome either way)
    try:
        req = urllib.request.Request(
            base + "/api/notes", method="POST",
            data=json.dumps({"title": "یادداشت آزمایشی",
                             "body": "ساخت با مدل"}).encode(),
            headers={"Content-Type": "application/json"})
        with urllib.request.urlopen(req, timeout=10) as resp:
            print("POST /api/notes ->", resp.status, resp.read()[:120].decode("utf-8", "replace"))
    except urllib.error.HTTPError as e:
        print("POST /api/notes ->", e.code, e.read()[:160].decode("utf-8", "replace"))
    except Exception as exc:                # noqa: BLE001
        print("POST /api/notes error:", exc)

    api("POST", "/api/factory/stop", {"project": PROJ})
    api("POST", "/api/factory/delete", {"project": PROJ, "confirm": True})
    print("cleanup ok (project removed)")


if __name__ == "__main__":
    main()
